         ga(2) = ga(2) - cc*wblk(1)*((2.0_dp*al*sy(1,0))*sx(1,2)*sz(0,0)) &
                         + cc*dblk(1)*((2.0_dp*al*ty(1,0))*sx(1,2)*sz(0,0) + (2.0_dp*al*sy(1,0))*(tx(1,2)*sz(0,0) + sx(1,2)*tz(0,0)))
         gb(2) = gb(2) + cc*wblk(1)*((2.0_dp*al*sy(1,0))*sx(1,2)*sz(0,0)) &
                         - cc*dblk(1)*((2.0_dp*al*ty(1,0))*sx(1,2)*sz(0,0) + (2.0_dp*al*sy(1,0))*(tx(1,2)*sz(0,0) + sx(1,2)*tz(0,0)))
         ga(3) = ga(3) - cc*wblk(1)*((2.0_dp*al*sz(1,0))*sx(1,2)*sy(0,0)) &
